    'asterisk_settings.rtp_section_title' => 'RTP-instellingen (media)',
    'asterisk_settings.rtp_help_body' => 'Bepaalt welk poortbereik audio (RTP) transporteert en of Asterisk audio van een onverwachte bron weigert. Dit bestand (<code>/etc/asterisk/rtp.conf</code>) wordt nu door het paneel gegenereerd; handmatige wijzigingen op de server gaan bij de volgende "Toepassen" verloren.',
    'asterisk_settings.field_rtp_start' => 'RTP-beginpoort',
    'asterisk_settings.rtp_start_help' => 'Begin van het poortbereik dat voor audiostreams is gereserveerd. Elk gelijktijdig gesprek gebruikt poorten uit dit bereik.',
    'asterisk_settings.field_rtp_end' => 'RTP-eindpoort',
    'asterisk_settings.rtp_end_help' => 'Einde van het bereik. coturn (TURN-relay) gebruikt 13479-14999 — een overlap breekt WebRTC-audio en wordt bij opslaan geweigerd.',
    'asterisk_settings.field_rtp_strict' => 'Strikte RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Indien ingeschakeld, laat Asterisk audio die van een andere bron dan het geleerde externe adres/de geleerde poort komt stilzwijgend vallen (bescherming tegen aanvallen). Als de PBX aan de andere kant media vanaf een onverwachte poort stuurt, veroorzaakt dit een stille "geen audio"-storing zonder spoor in de logs — het kan tijdelijk worden uitgeschakeld voor diagnose.',
    'asterisk_settings.rtp_strict_yes' => 'Ingeschakeld (aanbevolen)',
    'asterisk_settings.rtp_strict_no' => 'Uitgeschakeld (voor diagnose)',
    'asterisk_settings.rtp_restart_warning' => 'De instelling Strikte RTP wordt actief met "Toepassen". Een wijziging van het POORTBEREIK vereist echter een volledige herstart van Asterisk — de poortpool wordt eenmalig toegewezen wanneer de module laadt.',
    'asterisk_settings.udptl_section_title' => 'T.38 UDPTL-instellingen (faxmedia)',
    'asterisk_settings.udptl_help_body' => 'Definieert UDP-poortbereiken en parameters voor voorwaartse foutcorrectie (FEC / checksum) voor T.38-faxpakketten (UDPTL). Dit bestand (<code>/etc/asterisk/udptl.conf</code>) wordt dynamisch beheerd.',
    'asterisk_settings.field_udptl_start' => 'UDPTL-beginpoort',
    'asterisk_settings.udptl_start_help' => 'Begin-UDP-poort voor T.38-faxstreams (standaard: 4100).',
    'asterisk_settings.field_udptl_end' => 'UDPTL-eindpoort',
