    'trunks.field_connection_mode' => 'Verbindingsmodus',
    'trunks.connection_mode_ip' => 'Op IP-basis (peer heeft een vast IP)',
    'trunks.connection_mode_register' => 'Inkomende registratie (peer registreert bij ons)',
    'trunks.connection_mode_help' => 'Op IP-basis: de peer wordt herkend aan zijn IP-adres en het contact blijft statisch — de aanbevolen modus voor een peer met een vast IP op hetzelfde netwerk. Inkomende registratie: de peer stuurt ons een SIP REGISTER en het adres wordt uit die registratie geleerd. Deze modus vereist een gebruikersnaam en wachtwoord; de peer authenticeert daarmee zowel zijn registratie als zijn gesprekken.',
    'trunks.connection_mode_warning' => 'Overschakelen naar registratiemodus verwijdert het statische contact: we kunnen die trunk pas bellen NADAT de peer zich bij ons heeft geregistreerd. Voer deze wijziging uit in afstemming met de registratie-instelling aan de kant van de peer.',
