    'sound_packs.tab' => 'Asterisk-geluidspakketten',
    'sound_packs.title' => 'Officiële Asterisk-geluidspakketten',
    'sound_packs.help_title' => 'Asterisk-geluidspakketten',
    'sound_packs.help_body' => 'Downloadt en installeert de officiële systeemberichten en wachtmuziek van Asterisk vanaf <code>downloads.asterisk.org</code>. Elk pakket is één taal in één formaat; Asterisk speelt het formaat af dat bij de codec van het gesprek past en transcodeert anders (g722 voor G.722, ulaw/alaw voor providers).<br>- <strong>Core:</strong> systeemberichten, cijfers, voicemail. <strong>Extra:</strong> aanvullende berichten; het core-pakket van dezelfde taal moet eerst zijn geïnstalleerd.<br>- <strong>Wachtmuziek (opsound):</strong> wordt geïnstalleerd in <code>/var/lib/asterisk/moh/opsound</code>; om het af te spelen, maak je op het tabblad Wachtmuziek een MOH-klasse met de naam <strong>opsound</strong> aan.<br>- <strong>Türkçe (AiPBX):</strong> de eigen Turkse berichten van AiPBX (GitHub-release, SHA256-geverifieerd); de standaardtaal is Turks, dus als je ze verwijdert, vallen de systeemberichten stil. Verwijderen wist alleen de bestanden die het pakket heeft geïnstalleerd.',
