    'ms_teams.guide_title' => 'Gids Microsoft Teams-integratie',
    'ms_teams.guide_intro' => 'AiPBX kan op twee verschillende niveaus met Microsoft Teams communiceren:',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / SIP-trunk):',
    'ms_teams.guide_dr_desc' => 'Hiermee kunnen Teams-gebruikers interne en externe gesprekken voeren en ontvangen, direct vanaf het kiesscherm van Teams op desktop/mobiel. Vereist TLS (poort 5061), SRTP en een geldig openbaar SSL-certificaat (bijv. Let\'s Encrypt).',
