    'system_update.help_body' => 'De update maakt eerst een back-up van de database, instellingen en Asterisk-configuratie, installeert dan de nieuwe versie en test of alles werkt. Als er iets misgaat, wordt automatisch teruggekeerd naar de vorige versie. Asterisk wordt tijdens de update herstart: lopende gesprekken worden verbroken, dus de update start niet zolang er gesprekken actief zijn. Je kunt de update ook op de server uitvoeren: <code>sudo aipbx-update</code>',
