    'certificates.help_title' => 'Certificaathandleiding',
    'certificates.help_body' => 'Het portaal (HTTPS), WebRTC TURNS en SIP-TLS/WSS delen één certificaat; wijzigingen hier worden tegelijk toegepast op Apache, coturn en Asterisk. <b>Let\'s Encrypt</b> is gratis en vernieuwt zichzelf; het domein moet naar deze server verwijzen en poort 80 moet vanaf internet bereikbaar zijn. Heeft je organisatie een eigen certificaat, <b>upload het dan</b> (PEM of PFX); geüploade certificaten worden niet automatisch vernieuwd, upload een nieuw certificaat voordat het verloopt. Met een <b>self-signed</b> certificaat tonen browsers een waarschuwing en werkt TURNS niet in browsers: WebRTC-gesprekken achter firewalls hebben dan mogelijk geen geluid.',
