    'queue_reports.title' => 'Wachtrijrapportage',
    'queue_reports.help_title' => 'Handleiding wachtrijrapporten',
    'queue_reports.help_body' => 'Elk gesprek dat in een wachtrij komt, wordt één keer geteld. <b>Beantwoord</b>: verbonden met een agent. <b>Verloren</b>: de beller hing op tijdens het wachten of de wachtrij liep af (time-out). <b>Kort opgehangen</b>: binnen %d seconden opgehangen; telt niet mee voor het serviceniveau. <b>Serviceniveau</b>: gesprekken die binnen de doeltijd zijn beantwoord, ten opzichte van alle gesprekken behalve kort opgehangen. <b>ASA</b>: gemiddelde wachttijd van beantwoorde gesprekken. <b>AHT</b>: gemiddelde gespreksduur. <b>Opnamepercentage</b> (agent): hoe vaak de agent opnam als de wachtrij hem liet overgaan. <b>Terugbellen</b>: een verloren gesprek telt als afgehandeld als het nummer later vanaf een toestel is gebeld, of opnieuw belde en werd beantwoord. De gegevens komen uit de queue log van Asterisk; het rapport kan als PDF of Excel worden gedownload.',
