    'ai_models.help_title' => 'AI-modellen op deze server',
    'ai_models.help_body' => 'Voert AI-modellen uit op de centrale zelf: tekst en audio verlaten de server nooit, en er is geen API-sleutel of kosten aan verbonden. Installeer eerst de <strong>lokale AI-runtime</strong> (ongeveer 160 MB schijfruimte, eenmalig gedownload), download vervolgens de benodigde modellen en accepteer hun licentie. Een model verbruikt geheugen en CPU zolang het is geladen; de snelheidstest laat zien of het snel genoeg is op deze server. Oproepen behouden prioriteit: de service draait met een lagere CPU-prioriteit en een geheugenlimiet. Zie docs/local-ai.md.',
