    'ai_apps.help_title' => 'AI-toepassingen met eigen nummers',
    'ai_apps.help_body' => 'Een AI-toepassing beantwoordt een oproep, voert zijn taak uit en schakelt het gesprek door naar een bestemming. Geef deze een intern nummer om er direct naartoe te bellen, of kies het als bestemming in IVR\'s, inkomende routes en tijdcondities ("AI-toepassing"). <strong>Aankondiging met waarden</strong>: een tekst die aan de beller wordt voorgelezen door een stemmodel van deze server, met waarden erin — {caller_number}, {caller_name}, {did} zijn afkomstig van de oproep, elke andere {name} uit uw eigen systeem via het opzoekadres. Wijzigingen worden van kracht met <strong>Toepassen</strong>.',
