    'ai_tts.help_title' => 'Handleiding Cloud TTS',
    'ai_tts.help_body' => 'Zet tekst om in natuurlijke spraak met clouddiensten (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Beluister het resultaat, download het als MP3 of sla het met één klik op als <b>aankondiging</b>: het wordt omgezet naar het formaat van Asterisk (8 kHz WAV) en toegevoegd aan Geluiden &amp; aankondigingen voor IVR\'s, inkomende routes en tijdsvoorwaarden (actief na Toepassen). <b>Deze diensten zijn betaald</b> en rekenen per teken af; elke synthese wordt met het aantal tekens in de geschiedenis bewaard. Toegangssleutels komen uit de console van elke aanbieder, worden versleuteld opgeslagen en nooit meer op de pagina getoond.',
