    'push.help_intro' => 'De mobiele softphone van AI PBX heeft een <strong>gelaagde meldingsarchitectuur</strong>:',
    'push.help_layer0' => '<strong>Laag 0 (geen afhankelijkheid - standaard):</strong> een permanente WSS-verbinding, een voor Android 15 geschikte <code>specialUse</code>-voorgrondservice en een Doze-bestendige <code>AlarmManager</code>-watchdog die hem weer opstart. Er is geen externe dienst nodig; gesprekken komen binnen, zelfs als het apparaat inactief is of het scherm uit staat.',
    'push.help_layer1' => '<strong>Laag 1 (optioneel - Google FCM):</strong> een extra garantie om het apparaat te wekken op OEM-toestellen met agressieve batterijbeperkingen (Xiaomi, Huawei...) of als de gebruiker de app heeft weggeveegd. <em>Dit wordt alleen gebruikt als het toestel geen actieve SIP-registratie heeft, dus geregistreerde toestellen merken geen vertraging.</em>',
    'push.help_no_fcm' => 'Wil je geen FCM, laat de provider dan op <strong>„Lokaal (geen afhankelijkheid)”</strong> staan. De mobiele app maakt dan helemaal geen netwerkcontact met Google.',
