    'mailtpl.invite_new.subject' => '[{brand}] Je account is aangemaakt - stel je wachtwoord in',
    'mailtpl.invite_new.body' => '<p>Hallo {name},</p>{mobile_section}<p>Je account op de telefooncentrale <strong>{brand}</strong> is klaar. Stel met de knop hieronder je wachtwoord in om je aan te melden.</p>{account_details}{reset_button}<p>Werkt de knop niet? Open dan deze link: {reset_link}</p><p><em>De wachtwoordlink is 48 uur geldig en werkt één keer. Verwachtte je deze e-mail niet? Neem dan contact op met je systeembeheerder.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Je aanmeld- en wachtwoordlink',
    'mailtpl.invite.body' => '<p>Hallo {name},</p>{mobile_section}<p>Hier is een nieuwe link om je wachtwoord voor <strong>{brand}</strong> in te stellen.</p>{account_details}{reset_button}<p>Werkt de knop niet? Open dan deze link: {reset_link}</p><p><em>De wachtwoordlink is 48 uur geldig en werkt één keer. Heb je hem niet aangevraagd? Neem dan contact op met je systeembeheerder.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Stel je wachtwoord opnieuw in',
    'mailtpl.password_reset.body' => '<p>Hallo {name},</p><p>Er is gevraagd om het wachtwoord van je account <strong>{username}</strong> opnieuw in te stellen.</p>{reset_button}<p>Werkt de knop niet? Open dan deze link: {reset_link}</p><p><em>De link is 30 minuten geldig. Heb je dit niet aangevraagd? Negeer deze e-mail dan; je wachtwoord blijft hetzelfde.</em></p>',
    'mailtpl.voicemail.subject' => 'Nieuwe voicemail van {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Hallo {name},</p><p>Je hebt een nieuw voicemailbericht in voicemailbox <strong>{mailbox}</strong>.</p><ul><li><strong>Van:</strong> {caller}</li><li><strong>Ontvangen:</strong> {date}</li><li><strong>Lengte:</strong> {duration}</li></ul><p>Als de opname is bijgevoegd, kun je hem hier direct afspelen. Je kunt hem ook beluisteren in het portaal ({portal_link}) of door *97 te bellen.</p>',
    'mailtpl.fax_received.subject' => 'Nieuwe fax ontvangen - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Er is een nieuwe fax ontvangen.</p><ul><li><strong>Afdeling:</strong> {department}</li><li><strong>Faxnummer:</strong> {did}</li><li><strong>Van:</strong> {caller}</li><li><strong>Pagina\'s:</strong> {pages}</li><li><strong>Ontvangen:</strong> {date}</li></ul><p>De fax is als pdf bijgevoegd als die optie aanstaat. Alle faxen staan in de faxinbox: {portal_link}</p>',
