    'mailtpl.fax_sent.body' => '<p>Je fax is afgeleverd.</p><ul><li><strong>Aan:</strong> {destination}</li><li><strong>Pagina\'s:</strong> {pages}</li><li><strong>Tijd:</strong> {date}</li></ul><p>Verzonden faxen: {portal_link}</p>',
