    'storage.help_title' => 'Waar chatbestanden worden bewaard',
    'storage.help_body' => '<p>Chatbijlagen, hun miniaturen en groepsafbeeldingen worden standaard op de schijf van de server opgeslagen (<code>/var/lib/aipbx/chat_files</code>). Met een S3-compatibele opslag (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) gaan ze in plaats daarvan naar een bucket en blijven grote bestanden van de PBX af.</p><p>Downloads blijven via de chatdienst lopen, zodat alleen de deelnemers van een chat de bestanden ervan kunnen openen; de bucket kan privé blijven. Bestanden die vóór de overstap zijn opgeslagen, worden nog vanaf de schijf geleverd totdat je ze verplaatst. De bucketinstellingen worden gecontroleerd voordat ze worden opgeslagen.</p><p>Gespreksopnamen, voicemail en faxen blijven op de lokale schijf.</p>',
