    'netsvc.help_title' => 'Netwerkdiensten',
    'netsvc.help_body' => 'Bureautoestellen vinden de provisioningserver zelf wanneer de DHCP-server het adres ervan uitdeelt (optie 66). DHCP en TFTP worden apart ingeschakeld. Met <strong>DHCP-server</strong> uit blijft je eigen DHCP-server in gebruik: stel daar de hieronder vermelde opties in. Met de optie aan deelt AiPBX adressen uit op één interface of VLAN. <strong>TFTP-server</strong> levert de opstartbestanden en firmware die je uploadt. De configuratie per telefoon (met het SIP-wachtwoord) wordt altijd via HTTPS geleverd, nooit via TFTP.',
