    'web_widgets.help_body' => 'Een widget plaatst een knop "Bel ons" op elke website. Bezoekers praten met je vanuit de browser via WebRTC, of laten hun nummer achter en de PBX belt hen. Plak de code van één regel in de website (of in de WordPress-plugin) en klik na het opslaan op <strong>Toepassen</strong>.',
    'web_widgets.help_number' => 'Nummer:',
    'web_widgets.help_number_desc' => 'Een widget komt de PBX binnen als een trunk. Het nummer is de DID van deze gesprekken in rapporten en CDR; de bezoeker kiest nooit waar het gesprek heen gaat.',
    'web_widgets.help_security' => 'Beveiliging:',
    'web_widgets.help_security_desc' => 'Alleen de toegestane websites kunnen de widget gebruiken. Elk gesprek vereist een eenmalig token, en de limieten (per IP, per dag, gelijktijdige gesprekken, gespreksduur) gelden voor elk verzoek. Elk verzoek wordt hieronder gelogd.',
    'web_widgets.help_callback' => 'Terugbellen:',
    'web_widgets.help_callback_desc' => 'De PBX belt de bezoeker via de gekozen uitgaande route en stuurt hem bij beantwoording door naar de bestemming. Alleen nummers die met de toegestane prefixen beginnen, worden gebeld, en een daglimiet is verplicht.',
